"""Private static shells: never embed submission data, tokens, or mail credentials."""
import json

def render_editorial_pages(root):
    def page(name,title,body,script):
        (root/name).write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer"><title>{title} · Kabita Live</title><link rel="stylesheet" href="assets/editor-workspace.css"><link rel="stylesheet" href="assets/editorial-desk.css"><script type="module" src="assets/{script}"></script></head><body><header><a class="brand" href="index.html">Kabita Live</a><span>{title}</span></header><main class="editorial-desk" data-pagefind-ignore="all">{body}</main></body></html>''')
    page('author-proof.html','Your poem proof','''<h1 id="proof-title">Your private poem proof</h1><p id="proof-status" role="status">Opening your proof…</p><section id="proof-content" hidden><p id="proof-byline"></p><p id="proof-expiry"></p><img id="proof-art" alt="Artwork prepared for this poem"><div id="proof-languages"></div><form id="proof-comment" method="post" action="#"><label for="proof-message">Corrections or comments</label><textarea id="proof-message" name="message" maxlength="5000" rows="7" required></textarea><p>These comments go privately to the editors. They do not change the poem directly.</p><button type="submit">Send correction comments</button></form></section><noscript>Enable JavaScript to open this private proof. No login is needed.</noscript>''','author-proof.mjs')
    page('editor-management.html','Comments & statistics','''<h1>Comments &amp; statistics</h1><a href="editor-workspace.html">Return to Editor Studio</a><p id="management-status" role="status">Preparing sign-in…</p><button id="management-login" type="button" disabled>Sign in with Google</button><button id="management-logout" type="button" hidden>Sign out</button><section id="management-content" hidden><h2>Reader comments</h2><p>Removing a comment takes it off the website and preserves a private moderation record.</p><label for="comment-source">Comment collection</label><select id="comment-source"><option value="poems">Poem comments</option><option value="articles">Article comments</option></select><label for="comment-filter">Find in loaded comments · article, name or words</label><input type="search" id="comment-filter"><label for="comment-status">Status</label><select id="comment-status"><option value="">All</option><option value="pending">Pending</option><option value="published">Published</option><option value="withdrawn">Removed</option><option value="rejected">Rejected</option></select><div id="comment-list"></div><button id="comments-more" type="button">Load more comments</button><h2>Visits &amp; share activity</h2><button id="statistics-refresh" type="button">Refresh statistics</button><div id="statistics"></div><section id="owner-publication" hidden><h2>Final publication · owner only</h2><p>Review the exact prepared release before approving the protected publication workflow. Editors cannot publish.</p><a id="owner-publish" rel="noopener" target="_blank">Open final publication</a></section></section>''','editor-management.mjs')
    rows=[]
    for art in json.loads((root/'data/poem-art-library.json').read_text()).get('artworks',[]):
        if (root/art['src']).exists(): rows.append({'src':art['src'],'label':art.get('caption',art['id'])})
    (root/'assets/editor-proof-art.json').write_text(json.dumps(rows,ensure_ascii=False))
